static void vg_ui_screen_delete_cb(FAR lv_event_t *event)
{
  FAR lv_obj_t *target = lv_event_get_target(event);

  if (target == g_active_screen)
    {
      vg_ui_clear_page_refs();
      g_active_screen = NULL;
    }
