    if 'fonts' in str(p) or 'assets' in str(p):
        continue
    srcs.append(p.read_text(encoding='utf-8', errors='ignore'))
text='\n'.join(srcs)
# find chinese runs
chars=set(re.findall(r'[\u4e00-\u9fff]', text))
missing=sorted(c for c in chars if c not in opts16)
print('unique cn', len(chars), 'missing', ''.join(missing) if missing else 'none')
if missing:
    # show contexts
    for c in missing:
        for line in text.splitlines():
            if c in line and ('"' in line or "'" in line):
                print(c, '->', line.strip()[:120])
                break
